if (customW) {
    customW.addEventListener('change', function() {
        var lp = getCurrentLabelPresetUi();
        resizeBarcodePreviewForCurrentLabelSize();
        if (showBarcodeCustomSizeFields() && currentBarcodeMetalKey) {
            loadBarcodeSettingsForMetalAndLabel(currentBarcodeMetalKey, lp.ui, lp.w, lp.h);
        }
    });
}
if (customH) {
    customH.addEventListener('change', function() {
